<script setup>
import AdminNavigation from '@/Components/Admin/AdminNavigation.vue'; import CustomerTabs from '@/Components/Admin/CustomerTabs.vue'; import InputError from '@/Components/InputError.vue'; import PortalLayout from '@/Layouts/PortalLayout.vue'; import { Head,Link,router,useForm } from '@inertiajs/vue3'; const props=defineProps({customer:{type:Object,required:true},activeTab:{type:String,required:true},activity:{type:Array,required:true},moduleRecords:{type:Object,required:true}}); const noteForm=useForm({body:'',is_private:true}); const addNote=()=>noteForm.post(route('admin.customers.notes.store',props.customer.id),{preserveScroll:true,onSuccess:()=>noteForm.reset('body')}); const remove=()=>{if(window.confirm(`Delete ${props.customer.name}? This cannot be undone.`))router.delete(route('admin.customers.destroy',props.customer.id));}; const emptyMessages={subscriptions:'No subscriptions are linked to this customer yet.',invoices:'No invoices have been issued to this customer yet.',payments:'No payments have been recorded for this customer yet.',licenses:'No software licenses are linked to this customer yet.',support:'No support tickets are linked to this customer yet.'};
</script>
<template><Head :title="customer.name"/><PortalLayout area="Administration"><template #navigation><AdminNavigation active="customers"/></template><div v-if="$page.props.flash.success" class="success-message mb-5">{{ $page.props.flash.success }}</div><div class="mb-6 flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between"><div><Link :href="route('admin.customers.index')" class="text-sm font-bold text-cyan-700">← Customers</Link><div class="mt-2 flex flex-wrap items-center gap-3"><h1 class="text-3xl font-bold">{{ customer.name }}</h1><span class="rounded-full bg-white px-3 py-1 text-xs font-bold uppercase shadow-sm">{{ customer.status }}</span></div><p class="mt-2 text-slate-500">{{ customer.customer_number }} · {{ customer.type }}</p></div><div class="flex gap-2"><Link :href="route('admin.customers.edit',customer.id)" class="form-button">Edit</Link><button class="rounded-xl border border-red-200 bg-white px-5 py-3 font-bold text-red-700" @click="remove">Delete</button></div></div><div class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><CustomerTabs :customer-id="customer.id" :active="activeTab"/><div class="p-6">
<div v-if="activeTab==='overview'" class="space-y-8"><div class="grid gap-6 lg:grid-cols-3"><section class="lg:col-span-2"><h2 class="text-xl font-bold">Customer overview</h2><dl class="mt-4 grid gap-4 sm:grid-cols-2"><div><dt class="text-xs font-bold uppercase text-slate-400">Email</dt><dd class="mt-1">{{ customer.email||'—' }}</dd></div><div><dt class="text-xs font-bold uppercase text-slate-400">Phone</dt><dd class="mt-1">{{ customer.phone||'—' }}</dd></div><div><dt class="text-xs font-bold uppercase text-slate-400">Website</dt><dd class="mt-1"><a v-if="customer.website" :href="customer.website" class="text-cyan-700" target="_blank" rel="noopener noreferrer">{{ customer.website }}</a><span v-else>—</span></dd></div><div><dt class="text-xs font-bold uppercase text-slate-400">Tax ID</dt><dd class="mt-1">{{ customer.tax_id||'—' }}</dd></div><div><dt class="text-xs font-bold uppercase text-slate-400">Source</dt><dd class="mt-1">{{ customer.source||'—' }}</dd></div><div><dt class="text-xs font-bold uppercase text-slate-400">Assigned to</dt><dd class="mt-1">{{ customer.assigned_user?.name||'Unassigned' }}</dd></div><div class="sm:col-span-2"><dt class="text-xs font-bold uppercase text-slate-400">Billing address</dt><dd class="mt-1 whitespace-pre-line">{{ customer.billing_address||'—' }}<span v-if="customer.city">, {{ customer.city }}</span><span v-if="customer.state">, {{ customer.state }}</span></dd></div></dl></section><aside class="rounded-2xl bg-slate-50 p-5"><h2 class="font-bold">Relationship summary</h2><dl class="mt-4 space-y-3 text-sm"><div class="flex justify-between"><dt>Products</dt><dd class="font-bold">{{ customer.products.length }}</dd></div><div class="flex justify-between"><dt>Contacts</dt><dd class="font-bold">{{ customer.contacts.length }}</dd></div><div class="flex justify-between"><dt>Addresses</dt><dd class="font-bold">{{ customer.addresses.length }}</dd></div><div class="flex justify-between"><dt>Notes</dt><dd class="font-bold">{{ customer.notes.length }}</dd></div></dl></aside></div><section><h2 class="text-xl font-bold">Internal notes</h2><form class="mt-4 rounded-xl bg-slate-50 p-4" @submit.prevent="addNote"><textarea v-model="noteForm.body" required rows="3" class="w-full" placeholder="Add account context, follow-up details, or internal observations."/><InputError :message="noteForm.errors.body"/><div class="mt-3 flex items-center justify-between"><label class="flex items-center gap-2 text-sm"><input v-model="noteForm.is_private" type="checkbox" class="!mt-0"/>Internal note</label><button class="form-button !px-4 !py-2" :disabled="noteForm.processing">Add note</button></div></form><div class="mt-4 space-y-3"><article v-for="note in customer.notes" :key="note.uuid" class="rounded-xl border border-slate-200 p-4"><p class="whitespace-pre-line text-slate-700">{{ note.body }}</p><p class="mt-2 text-xs text-slate-500">{{ note.author?.name||'System' }} · {{ new Date(note.created_at).toLocaleString() }}</p></article><p v-if="!customer.notes.length" class="text-sm text-slate-500">No notes have been added.</p></div></section></div>
<div v-else-if="activeTab==='contacts'"><h2 class="text-xl font-bold">Contacts</h2><div class="mt-5 grid gap-4 md:grid-cols-2"><article v-for="contact in customer.contacts" :key="contact.uuid" class="rounded-xl border border-slate-200 p-5"><div class="flex justify-between"><h3 class="font-bold">{{ contact.name }}</h3><span v-if="contact.is_primary" class="text-xs font-bold text-cyan-700">PRIMARY</span></div><p class="mt-1 text-sm text-slate-500">{{ contact.job_title||'Contact' }}</p><p class="mt-3 text-sm">{{ contact.email||'—' }}<br/>{{ contact.phone||'—' }}</p></article><p v-if="!customer.contacts.length" class="text-slate-500">No contacts have been added.</p></div></div>
<div v-else-if="activeTab==='products'"><h2 class="text-xl font-bold">KernelBridge products</h2><div class="mt-5 grid gap-4 md:grid-cols-2 lg:grid-cols-3"><article v-for="product in customer.products" :key="product.uuid" class="rounded-xl border border-slate-200 p-5"><p class="text-xs font-bold text-cyan-700">{{ product.code }}</p><h3 class="mt-1 text-lg font-bold text-[#0B3D6E]">{{ product.name }}</h3><Link :href="route('admin.products.show',product.slug)" class="mt-4 inline-flex text-sm font-bold text-cyan-700">View product →</Link></article><p v-if="!customer.products.length" class="text-slate-500">No products are linked to this customer.</p></div></div>
<div v-else-if="['subscriptions','invoices','payments','licenses','support'].includes(activeTab)"><h2 class="text-xl font-bold capitalize">{{ activeTab }}</h2><div v-if="moduleRecords[activeTab].length" class="mt-5"><!-- Records use the relevant module resource once that module is installed. --></div><div v-else class="mt-5 rounded-xl bg-slate-50 p-8 text-center text-slate-500">{{ emptyMessages[activeTab] }}</div></div>
<div v-else-if="activeTab==='activity'"><h2 class="text-xl font-bold">Activity</h2><ol class="mt-5 space-y-4"><li v-for="entry in activity" :key="entry.id" class="border-l-2 border-cyan-200 pl-4"><p class="font-bold">{{ entry.event.replaceAll('.',' ') }}</p><time class="text-xs text-slate-500">{{ new Date(entry.created_at).toLocaleString() }}</time></li><li v-if="!activity.length" class="text-slate-500">No recorded activity.</li></ol></div>
</div></div></PortalLayout></template>
